package orchestrator.registry

import java.net.{URI, URL, IDN}
import java.nio.charset.StandardCharsets
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object UnicodeUtils {
  // Normalize registry hostname to ASCII for safe comparison
  def normalizeHostname(host: String): String = {
    val nfkc = java.text.Normalizer.normalize(host, java.text.Normalizer.Form.NFKC)
    Try(IDN.toASCII(nfkc, IDN.USE_STD3_ASCII_RULES)).getOrElse(nfkc)
  }

  def isAsciiOnly(s: String): Boolean = {
    s.forall(c => c >= 0x20 && c <= 0x7E)
  }

  def validateHostname(host: String): Either[String, String] = {
    val normalized = normalizeHostname(host)
    if (!isAsciiOnly(normalized)) {
      Left(s"Hostname contains non-ASCII characters after normalization: $host")
    } else if (normalized.isEmpty || normalized.length > 253) {
      Left(s"Invalid hostname length: $host")
    } else {
      Right(normalized)
    }
  }

  // Validate repository path component: allow lowercase alnum, separators, and slashes
  // per OCI/Docker naming, but reject traversal and injection characters.
  private val RepoPattern = "^[a-z0-9]+(?:(?:[._]|__|[-]+)[a-z0-9]+)*(?:/[a-z0-9]+(?:(?:[._]|__|[-]+)[a-z0-9]+)*)*$".r
  def validateRepository(repo: String): Either[String, String] = {
    if (repo.isEmpty || repo.length > 255) {
      Left(s"Invalid repository length: $repo")
    } else if (repo.contains("..") || repo.contains("@")) {
      Left(s"Repository contains illegal characters: $repo")
    } else if (RepoPattern.findFirstIn(repo).isEmpty) {
      Left(s"Invalid repository name: $repo")
    } else {
      Right(repo)
    }
  }

  // Validate image tag: alnum, underscore, period, dash; max 128 chars.
  private val TagPattern = "^[a-zA-Z0-9_][a-zA-Z0-9._-]{0,127}$".r
  def validateTag(tag: String): Either[String, String] = {
    if (TagPattern.findFirstIn(tag).isEmpty) {
      Left(s"Invalid tag: $tag")
    } else {
      Right(tag)
    }
  }
}

case class RegistryConfig(
  name: String,
  endpoint: String,
  trustedCert: Option[String],
  allowInsecure: Boolean = false
)

case class ImageReference(
  registry: String,
  repository: String,
  tag: String
) {
  def fullName: String = s"$registry/$repository:$tag"
}

trait RegistryAuthenticator {
  def authenticate(registry: String): Option[String]
}

class TrustedRegistryManager(configs: Seq[RegistryConfig]) {

  private val trustedRegistries: mutable.Map[String, RegistryConfig] = {
    val m = mutable.Map.empty[String, RegistryConfig]
    configs.foreach { cfg =>
      val normalized = UnicodeUtils.normalizeHostname(cfg.endpoint)
      m.put(normalized, cfg)
    }
    m
  }

  // Check if a registry endpoint is in our trusted list
  def isTrusted(registryHost: String): Boolean = {
    val normalized = UnicodeUtils.normalizeHostname(registryHost)
    trustedRegistries.contains(normalized)
  }

  def getConfig(registryHost: String): Option[RegistryConfig] = {
    val normalized = UnicodeUtils.normalizeHostname(registryHost)
    trustedRegistries.get(normalized)
  }
}

class ContainerImageResolver(
  registryManager: TrustedRegistryManager,
  authenticator: RegistryAuthenticator
) {

  // Parse image reference from user-provided string
  def parseImageRef(imageStr: String): Either[String, ImageReference] = {
    val parts = imageStr.split("/", 2)
    if (parts.length < 2) {
      Left(s"Invalid image reference: $imageStr")
    } else {
      val registry = parts(0)
      val repoParts = parts(1).split(":")
      val repo = repoParts(0)
      val tag = if (repoParts.length > 1) repoParts(1) else "latest"
      Right(ImageReference(registry, repo, tag))
    }
  }

  // Validate that image comes from a trusted registry
  // Uses NFKC + IDN normalization and validates ASCII-only result
  def validateImageSource(ref: ImageReference): Either[String, ImageReference] = {
    UnicodeUtils.validateHostname(ref.registry) match {
      case Left(err) => Left(err)
      case Right(normalizedRegistry) =>
        if (registryManager.isTrusted(normalizedRegistry)) {
          // Return reference with the NORMALIZED registry name
          Right(ref.copy(registry = normalizedRegistry))
        } else {
          Left(s"Registry ${ref.registry} is not in the trusted list")
        }
    }
  }

  // Resolve and pull image - uses the validated normalized reference
  def resolveImage(imageStr: String): Either[String, String] = {
    for {
      ref <- parseImageRef(imageStr)
      validated <- validateImageSource(ref)
      validRepo <- UnicodeUtils.validateRepository(validated.repository)
      validTag <- UnicodeUtils.validateTag(validated.tag)
      token <- authenticator.authenticate(validated.registry) match {
        case Some(t) => Right(t)
        case None => Left("Authentication failed")
      }
    } yield {
      // Pull using the NORMALIZED hostname from validation
      pullImage(validated.registry, validRepo, validTag, token)
    }
  }

  private def pullImage(registry: String, repo: String, tag: String, token: String): String = {
    // In production this would make HTTP calls to the registry API
    // Using the normalized registry hostname for DNS resolution
    val pullUrl = s"https://$registry/v2/$repo/manifests/$tag"
    s"Pulling from $pullUrl with auth token"
  }
}

object ContainerOrchestrator {

  def loadRegistryConfigs(): Seq[RegistryConfig] = {
    val trustedEndpoints = sys.env.getOrElse(
      "TRUSTED_REGISTRIES",
      "registry.example.com,gcr.io,docker.io"
    ).split(",").map(_.trim)

    trustedEndpoints.map { endpoint =>
      RegistryConfig(
        name = endpoint,
        endpoint = endpoint,
        trustedCert = sys.env.get(s"REGISTRY_CERT_${endpoint.replace('.', '_').toUpperCase}")
      )
    }.toSeq
  }

  def createResolver(): ContainerImageResolver = {
    val configs = loadRegistryConfigs()
    val manager = new TrustedRegistryManager(configs)
    val auth = new RegistryAuthenticator {
      override def authenticate(registry: String): Option[String] = {
        // In production, would check credentials store
        // For trusted registries, always provide a token
        Some(s"bearer-token-for-$registry")
      }
    }
    new ContainerImageResolver(manager, auth)
  }

  def deployContainer(imageStr: String): Either[String, String] = {
    val resolver = createResolver()
    resolver.resolveImage(imageStr)
  }
}
